recipes.code:
{
  "inputs": [
    {
      "id": "opedd-payment-method-id",
      "type": "promptString",
      "description": "Stripe PaymentMethod id (pm_...) for autonomous per-article purchasing",
      "password": true
    },
    {
      "id": "opedd-buyer-token",
      "type": "promptString",
      "description": "Buyer API token (opedd_buyer_live_*) — enables licensed content retrieval",
      "password": true
    },
    {
      "id": "opedd-access-key",
      "type": "promptString",
      "description": "Enterprise access key (ent_*) — enables bulk feed tools",
      "password": true
    },
    {
      "id": "opedd-buyer-jwt",
      "type": "promptString",
      "description": "Buyer portal session JWT — enables account, audit, compliance + EU AI Act attestation tools",
      "password": true
    },
    {
      "id": "opedd-pub-bearer",
      "type": "promptString",
      "description": "Publisher API key (opedd_pub_*) — enables publisher content push + listing tools",
      "password": true
    }
  ],
  "servers": {
    "opedd": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "opedd-mcp@0.6.8"
      ],
      "env": {
        "OPEDD_BUYER_EMAIL": "<opedd-buyer-email>",
        "OPEDD_PAYMENT_METHOD_ID": "${input:opedd-payment-method-id}",
        "OPEDD_BUYER_TOKEN": "${input:opedd-buyer-token}",
        "OPEDD_ACCESS_KEY": "${input:opedd-access-key}",
        "OPEDD_BUYER_JWT": "${input:opedd-buyer-jwt}",
        "OPEDD_PUB_BEARER": "${input:opedd-pub-bearer}"
      }
    }
  }
}
